{
  "name": "I-7540D CAN总线以太网网关",
  "name_en": "I-7540D CAN Bus to Ethernet Gateway",
  "manufacturer": "ICPCON",
  "description": "这是一种将以太网/TCP连接转换为CAN总线通信的网关设备，用于把实验室电脑、测试台或自动化系统接入CAN网络。它适合用于CAN设备联机、总线状态监测、通信参数配置以及标准CAN数据帧的收发。",
  "description_en": "This device is a gateway that bridges Ethernet/TCP connections to a CAN bus network. It is used to connect laboratory computers, test benches, or automation systems to CAN-based equipment for bus status monitoring, communication configuration, and transmission and reception of standard CAN data frames.",
  "tag_hints": [
    "CAN bus",
    "Ethernet gateway",
    "TCP/IP communication",
    "industrial communication",
    "standard CAN frames",
    "CAN configuration"
  ],
  "actions": [
    {
      "action_name": "auto-host",
      "description": "获取或设置网关主机名或IP地址",
      "description_en": "Get or set the gateway hostname or IP address."
    },
    {
      "action_name": "auto-timeout",
      "description": "获取或设置通信超时时间",
      "description_en": "Get or set the communication timeout."
    },
    {
      "action_name": "auto-connected",
      "description": "获取连接状态",
      "description_en": "Get connection status."
    },
    {
      "action_name": "auto-get_status",
      "description": "读取网关状态",
      "description_en": "Read the gateway status."
    },
    {
      "action_name": "auto-clear_error",
      "description": "清除CAN错误标志和FIFO，可选重新初始化CAN硬件",
      "description_en": "Clear the CAN error flag and FIFO, optionally reinitialize the CAN hardware."
    },
    {
      "action_name": "auto-reboot",
      "description": "重启网关",
      "description_en": "Reboot the gateway."
    },
    {
      "action_name": "auto-get_can_config",
      "description": "获取CAN配置",
      "description_en": "Get the CAN configuration."
    },
    {
      "action_name": "auto-set_can_config",
      "description": "设置CAN配置",
      "description_en": "Set the CAN configuration."
    },
    {
      "action_name": "auto-standard_dataframe_query",
      "description": "发送标准CAN数据帧并读取响应",
      "description_en": "Send a standard CAN data frame and read the response."
    },
    {
      "action_name": "auto-standard_dataframe_write",
      "description": "发送标准CAN数据帧",
      "description_en": "Send a standard CAN data frame."
    }
  ]
}

